{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver korrekt definitionen af varig og étårsudgangspunktet (omkring et år, symptomer i mindst et år før ansøgning). Det udelader dog, at varigheden vedrører funktionsnedsættelsens art og grad, og at tidsbegrænset tillæg kan gives, når varighed er sandsynliggjort. Det nævner heller ikke, at tiden alene ikke afgør spørgsmålet. Svaret indeholder ingen direkte fejl, men er ikke fyldestgørende nok til at blive vurderet som juridisk dækkende."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Element 1 (varighed er grundlæggende og vedrører art og grad) mangler. Element 4 (tidsbegrænset tillæg ved sandsynliggjort varighed, ikke endeligt fastslået) mangler helt. Elementerne 2 og 3 er dækket."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge led i spørgsmålet: hvornår en funktionsnedsættelse er varig, og hvad der gælder, hvis den ikke er varig eller kronisk fra begyndelsen. Det indeholder ingen irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledningsafsnit."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Svaret angiver ingen kilde, så kildens gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Svaret angiver ingen kilde, så støtten mellem påstand og kilde kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle påstande svarer til vejledningens afsnit 3.4.1.1 i de udleverede passager. Svaret tilføjer ingen regel, betingelse eller myndighed uden støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer 'som udgangspunkt', 'omkring et år' og 'kan vurderes'. Det mangler dog forbeholdet om, at tidsforløbet alene ikke afgør varigheden, og at tidsbegrænset tillæg forudsætter sandsynliggjort varighed. Begge er krævede kvalifikationer i rubrikken."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende. Det går fra definitionen af varig til udgangspunktet om, at ikke-varige tilstande ikke giver ret, til muligheden for at vurdere tilstanden som varig efter omkring et år, og dette hænger logisk sammen."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger 'som udgangspunkt', 'kan dog vurderes' og 'normalt' i overensstemmelse med vejledningen. Det gør ikke étårsudgangspunktet til en absolut regel."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "partial",
      "reason": "Svaret behandler varig funktionsnedsættelse og definitionen af den, men fremstiller ikke eksplicit varighed som et selvstændigt vilkår for handicaptillæg i hele dets omfang, og det nævner ikke art og grad."
    },
    "A12": {
      "label": "yes",
      "reason": "Svaret dækker punktet fuldt ud: udgangspunktet om ikke at være berettiget, når tilstanden ikke var varig eller kronisk fra debut, muligheden for at vurdere den som varig efter omkring et år og kravet om symptomer eller følger i mindst et år før ansøgningstidspunktet."
    }
  },
  "overall_notes": "Svaret er korrekt, men ufuldstændigt. Det dækker definitionen af varig og étårsudgangspunktet, men udelader varighedens tilknytning til art og grad, muligheden for tidsbegrænset tillæg ved sandsynliggjort varighed og forbeholdet om, at tid alene ikke afgør varigheden. Der er ingen kildeangivelse, så C04 er not_met, og C05 og C06 er not_assessable."
}

